package com.nexora.documents.application;

// Where document bytes live (FR-DOC-01): local disk in the first release (LocalFileStorage). Keys are generated by
// the service, never taken from the client. Implementations never overwrite an existing key.
public interface FileStorage {

    void store(String key, byte[] content);

    byte[] read(String key);

    // Best-effort clean-up of a file whose metadata row could not be saved.
    void discard(String key);
}
